								"idealDuration": $ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].idealDuration : $workunits[id = $wu].idealDuration ,
								"setupDuration": $ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].setupDuration : $workunits[id = $wu].setupDuration ,
								"processDuration": $ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].processDuration : $workunits[id = $wu].processDuration ,
								"standardDuration": $ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].standardDuration : $workunits[id = $wu].standardDuration ,
								"scheduledDuration": $momentDuration(($momentDuration($ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].setupDuration : $workunits[id = $wu].setupDuration)
											.asMilliseconds()
											+ ($momentDuration($ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].setupDuration : $workunits[id = $wu].setupDuration)
												.asMilliseconds()
												* $quantityPerDist)
											+ $momentDuration($ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].processDuration : $workunits[id = $wu].processDuration).asMilliseconds()),'milliseconds'),
								"transitAfter": $ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].transitAfter : $workunits[id = $wu].transitAfter,
								"transitBefore": $ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].transitBefore : $workunits[id = $wu].transitBefore,
