								"producedQuantity": 0,
								"setupOperators": $ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].setupOperators : $workunits[id = $wu].setupOperators,
								"productionOperators": $ in $approvedWorkunits.workunitId ? $approvedWorkunits[workunitId = $wu].productionOperators : $workunits[id = $wu].productionOperators,
								"distributionStatusId": "Released",
								"workOrderProcessId": $curr.id,
								"workunitId":  $/*$lookup($state.context.REQUEST.data.workunits, $string(sequence))*/
							}
						}
					)
				)
		],
		"workOrderPayload": [
			{
				"update": { "workOrderStatusId": "Released" },
				"where": { "id": $state.context.REQUEST.data.workOrderNumber }
			}
		] 
	};
	$distGroups:=$groupBy($workOrderPayloads.workOrderProcessPayload, function ($v) { $v.create.workOrderProcessId });
	$dependencyPayload := [
		(
	
	$groups := $keys($distGroups);
	$groups#$i
		.(
		$lookup($distGroups, $groups[$i])
			.(
				$current := $;
				$lookup($distGroups, $groups[$i + 1])
					.{
						"create": {
							"childWorkOrderProcessDistributionId": $current
								.create
								.id,
							"parentWorkOrderProcessDistributionId": $.create.id
						}
					}
			))
)
