query Workunit($whereWU: WorkunitWhereInput, $whereAW: ApprovedWorkunitWhereInput) {
  workunit(where: $whereWU) {
    edges {
      node {
        id
        unitPerCycle
        setupOperators
        productionOperators
        standardDuration
        idealDuration
        cycleDuration
        setupDuration
        processDuration
        transitAfter
        transitBefore
      }
    }
  }
  approvedWorkunit(where: $whereAW){
    edges{
      node{
        id
        workunitId
        productStrategyProcessId
        unitPerCycle
        setupOperators
        productionOperators
        standardDuration
        idealDuration
        cycleDuration
        setupDuration
        processDuration
        transitAfter
        transitBefore
      }
    }
  }
}

data.transform:
(
	$workorderId := $cuid();
	$productStrategyProcesses := $leftOuterJoin( 
		workorderHeader.productStrategy.productStrategyProcesses.edges.node, 
		workorderProcessDistributions, 
		'id', 
		'id', 
		"selectedDistributions"
	);

	$default := function($v, $defaultValue){ $coalesce([$v, $defaultValue]) };


	$workorderProcessesInfo := $productStrategyProcesses[selectedDistributions.includeInWorkorder=true].(
		$workorderProcessId := $cuid();
		$currProductStrategyProcessId := id;
		$crrProductStrategyProcess := $;
		{
			"process": {
				"create": {
					"id": $workorderProcessId,
					"productStrategyProcessId": id,
					"workOrderId": $workorderId,
					"sequence": sequence,
					"standardPackQuantity": standardPackQuantity,
					"unitWeight": unitWeight,
					"description": description,
					"documentDesignId": documentDesignId,
					"imageId": imageId,
					"processId": processId
				}
			},
			"boms": assemblyBoms.edges.node.{
				"create": $~>|$|{"workOrderProcessId": $workorderProcessId}|
			},
			"distributions":[( 
				$selectedApprovedWorkcenters := $$.workorderProcessDistributions.selectedWorkunits[productStrategyProcessId=$currProductStrategyProcessId]; 
				$quantityPerDist := $ceil($number($$.workorderHeader.quantity) / $count($selectedApprovedWorkcenters)); 
				$selectedApprovedWorkcenters#$i.(
					$crrApprovedWorkcenter := $;
					{
					"create":{
						"name":$crrProductStrategyProcess.sequence & ":" & $crrProductStrategyProcess.processId & " - " & ($i+1),
						"dispatchSequence": ($first($state.context.largestDistributions[id=$crrApprovedWorkcenter.workunitId].**.maximum)~>$default(?, 0)) + ($i+1),
						"active": true,
						"cycleDuration": $default(cycleDuration.text, "PT0S") ,
						"idealDuration": $default(idealDuration.text, "PT0S"),
						"setupDuration": $default(setupDuration.text, "PT0S") ,
						"processDuration": $default(processDuration.text, "PT0S") ,
						"standardDuration": $default(standardDuration.text, "PT0S") ,
						"scheduledDuration":
							$momentDuration(
								$default(
									(setupDuration.milliseconds + (standardDuration.milliseconds * $quantityPerDist) + processDuration.milliseconds),
									0
								),
								"milliseconds"
							),
						"transitAfter": $default(transitAfter.text, "PT0S"),
						"transitBefore": $default(transitBefore.text,"PT0S"),
						"unitPerCycle": $default(unitPerCycle, 0),
						"quantity": $quantityPerDist,
						"producedQuantity": 0,
						"setupOperators": setupOperators,
						"productionOperators": productionOperators,
						"distributionStatusId": "Released",
						"workOrderProcessId": $workorderProcessId,
						"workunitId": workunitId
					}
				} )
			)]
		}
	);

	{
		"workOrderPayload": [
			workorderHeader.{
					"create": {
						"id": $workorderId,
						"quantity": $number(quantity),
						"dueAt": dueAt,
						"earliestStartAt": earliestStartAt,
						"productStrategyId": productStrategy.id,
						"productId": productStrategy.product.id,
						"workOrderStatusId": $count($workorderProcessesInfo.distributions) > 0? "Released" : "Planned",
						"buildToOrder": type = "Build To Order",
						"buildToStock": type = "Build To Stock",
						"kanban": type = "Kanban"
					}
				}
		],
		"workOrderProcessPayload": [ $workorderProcessesInfo.process],
		"workOrderProcessBomPayload":[$workorderProcessesInfo.boms],
		"workOrderProcessDistributionPayload": [$workorderProcessesInfo.distributions]
	}
)

