		workorderHeader.productStrategy.productStrategyProcesses.edges.node, 
		workorderProcessDistributions, 
		'id', 
		'id', 
		"selectedDistributions"
	);

	$default := function($v, $defaultValue){ $coalesce([$v, $defaultValue]) };


	$workorderProcessesInfo := $productStrategyProcesses[selectedDistributions.includeInWorkorder=true].(
		$workorderProcessId := $cuid();
		$currProductStrategyProcessId := id;
		$crrProductStrategyProcess := $;
		{
