						"productionOperators": productionOperators,
						"distributionStatusId": "Released",
						"workOrderProcessId": $workorderProcessId,
						"workunitId": workunitId
					}
				} )
			)]
		}
	);

	{
		"workOrderPayload": [
			workorderHeader.{
					"create": {
						"id": $workorderId,
						"quantity": $number(quantity),
						"dueAt": dueAt,
						"earliestStartAt": earliestStartAt,
						"productStrategyId": productStrategy.id,
						"productId": productStrategy.product.id,
						"workOrderStatusId": $count($workorderProcessesInfo.distributions) > 0? "Released" : "Planned",
						"buildToOrder": type = "Build To Order",
						"buildToStock": type = "Build To Stock",
						"kanban": type = "Kanban"
					}
				}
		],
		"workOrderProcessPayload": [ $workorderProcessesInfo.process],
		"workOrderProcessBomPayload":[$workorderProcessesInfo.boms],
		"workOrderProcessDistributionPayload": [$workorderProcessesInfo.distributions]
	}
